CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_casecompliance]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_casecompliance]
	(
		[apuk_ageofcase],
		[apuk_areaofbreach],
		[apuk_areaofbreach_entitytype],
		[apuk_areaofbreach2],
		[apuk_areaofbreach2_entitytype],
		[apuk_areaofbreach2name],
		[apuk_areaofbreach3],
		[apuk_areaofbreach3_entitytype],
		[apuk_areaofbreach3name],
		[apuk_areaofbreachname],
		[apuk_areaofpractice],
		[apuk_areaofpractice_entitytype],
		[apuk_areaofpracticename],
		[apuk_arpdecision],
		[apuk_broker],
		[apuk_caseclosuredatetime],
		[apuk_casecomplexity],
		[apuk_casecomplianceid],
		[apuk_casegroupreference],
		[apuk_caseorigin],
		[apuk_casetype],
		[apuk_compliancecasereference],
		[apuk_dateclosed],
		[apuk_dateopened],
		[apuk_details],
		[apuk_dispensationoutcome],
		[apuk_escalationlevel],
		[apuk_failreason],
		[apuk_insurer],
		[apuk_name],
		[apuk_outcome],
		[apuk_primarylocationid],
		[apuk_primarylocationid_entitytype],
		[apuk_primarylocationidname],
		[apuk_regardingtype],
		[apuk_regulatedfirmid],
		[apuk_regulatedfirmid_entitytype],
		[apuk_regulatedfirmidname],
		[apuk_regulatedfirmidyominame],
		[apuk_regulatedindividualid],
		[apuk_regulatedindividualid_entitytype],
		[apuk_regulatedindividualidname],
		[apuk_regulatedindividualidyominame],
		[apuk_regulatedschemeid],
		[apuk_regulatedschemeid_entitytype],
		[apuk_regulatedschemeidname],
		[apuk_regulatorycontactid],
		[apuk_regulatorycontactid_entitytype],
		[apuk_regulatorycontactidname],
		[apuk_regulatorycontactidyominame],
		[apuk_regulatoryreturnid],
		[apuk_regulatoryreturnid_entitytype],
		[apuk_regulatoryreturnidname],
		[apuk_responsibleprincipalid],
		[apuk_responsibleprincipalid_entitytype],
		[apuk_responsibleprincipalidname],
		[apuk_responsibleprincipalidyominame],
		[apuk_ruleofconduct2],
		[apuk_ruleofconduct2_entitytype],
		[apuk_ruleofconduct2name],
		[apuk_showonline],
		[apuk_subject],
		[apuk_subject_entitytype],
		[apuk_subjectname],
		[apuk_urgent],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		DATEDIFF(DAY, stg.createdon, COALESCE(stg.apuk_dateclosed,GETDATE())),
		--stg.[apuk_ageofcase],
		stg.[apuk_areaofbreach],
		stg.[apuk_areaofbreach_entitytype],
		stg.[apuk_areaofbreach2],
		stg.[apuk_areaofbreach2_entitytype],
		stg.[apuk_areaofbreach2name],
		stg.[apuk_areaofbreach3],
		stg.[apuk_areaofbreach3_entitytype],
		stg.[apuk_areaofbreach3name],
		stg.[apuk_areaofbreachname],
		stg.[apuk_areaofpractice],
		stg.[apuk_areaofpractice_entitytype],
		stg.[apuk_areaofpracticename],
		stg.[apuk_arpdecision],
		stg.[apuk_broker],
		stg.[apuk_caseclosuredatetime],
		stg.[apuk_casecomplexity],
		stg.[apuk_casecomplianceid],
		stg.[apuk_casegroupreference],
		stg.[apuk_caseorigin],
		stg.[apuk_casetype],
		stg.[apuk_compliancecasereference],
		stg.[apuk_dateclosed],
		stg.[apuk_dateopened],
		stg.[apuk_details],
		stg.[apuk_dispensationoutcome],
		stg.[apuk_escalationlevel],
		stg.[apuk_failreason],
		stg.[apuk_insurer],
		stg.[apuk_name],
		stg.[apuk_outcome],
		stg.[apuk_primarylocationid],
		stg.[apuk_primarylocationid_entitytype],
		stg.[apuk_primarylocationidname],
		stg.[apuk_regardingtype],
		stg.[apuk_regulatedfirmid],
		stg.[apuk_regulatedfirmid_entitytype],
		stg.[apuk_regulatedfirmidname],
		stg.[apuk_regulatedfirmidyominame],
		stg.[apuk_regulatedindividualid],
		stg.[apuk_regulatedindividualid_entitytype],
		stg.[apuk_regulatedindividualidname],
		stg.[apuk_regulatedindividualidyominame],
		stg.[apuk_regulatedschemeid],
		stg.[apuk_regulatedschemeid_entitytype],
		stg.[apuk_regulatedschemeidname],
		stg.[apuk_regulatorycontactid],
		stg.[apuk_regulatorycontactid_entitytype],
		stg.[apuk_regulatorycontactidname],
		stg.[apuk_regulatorycontactidyominame],
		stg.[apuk_regulatoryreturnid],
		stg.[apuk_regulatoryreturnid_entitytype],
		stg.[apuk_regulatoryreturnidname],
		stg.[apuk_responsibleprincipalid],
		stg.[apuk_responsibleprincipalid_entitytype],
		stg.[apuk_responsibleprincipalidname],
		stg.[apuk_responsibleprincipalidyominame],
		stg.[apuk_ruleofconduct2],
		stg.[apuk_ruleofconduct2_entitytype],
		stg.[apuk_ruleofconduct2name],
		stg.[apuk_showonline],
		stg.[apuk_subject],
		stg.[apuk_subject_entitytype],
		stg.[apuk_subjectname],
		stg.[apuk_urgent],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_casecompliance] stg
		LEFT JOIN [synapse_ce].[apuk_casecompliance] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
